% --- Executes just before j_gui_old is made visible.
function j_gui_old_OpeningFcn(hObject, eventdata, handles, varargin)
global GUI_DATA
GUI_DATA.count = 0;
GUI_DATA.history = [];
handles.output = hObject;
handles.data = [];
set(handles.figure1, 'Name', 'Old lab GUI')
set(handles.text_status, 'String', 'ready')
guidata(hObject, handles);

% --- Outputs from this function are returned to the command line.
function varargout = j_gui_old_OutputFcn(hObject, eventdata, handles)
varargout{1} = handles.output;

% --- Executes on button press in pushbutton_load.
function pushbutton_load_Callback(hObject, eventdata, handles)
global GUI_DATA
[fname, pname] = uigetfile('*.dat', 'Pick a data file');
if isequal(fname, 0)
    return
end
handles.data = load([pname fname]);
GUI_DATA.count = GUI_DATA.count + 1;
GUI_DATA.history{GUI_DATA.count} = fname;
set(handles.text_status, 'String', ['loaded ' fname])
guidata(hObject, handles);

% --- Executes on button press in pushbutton_plot.
function pushbutton_plot_Callback(hObject, eventdata, handles)
if isempty(handles.data)
    msgbox('load a file first', 'Error', 'error')
    return
end
axes(handles.axes1)
cla
plot(handles.data(:, 1), handles.data(:, 2), 'b.-')
grid on
xlabel('time')
ylabel('signal')

% --- Executes on button press in pushbutton_save.
function pushbutton_save_Callback(hObject, eventdata, handles)
global GUI_DATA
fname = get(handles.edit_name, 'String');
data = handles.data;
save(fname, 'data', '-ascii')
disp(['saved to ' fname])
GUI_DATA.history{end+1} = fname;

% --- Executes on slider movement.
function slider_gain_Callback(hObject, eventdata, handles)
gain = get(hObject, 'Value');
set(handles.text_gain, 'String', num2str(gain, 3))
if ~isempty(handles.data)
    handles.scaled = handles.data(:, 2) * gain;
    guidata(hObject, handles);
end

% --- Executes during object creation, after setting all properties.
function slider_gain_CreateFcn(hObject, eventdata, handles)
if isequal(get(hObject, 'BackgroundColor'), get(0, 'defaultUicontrolBackgroundColor'))
    set(hObject, 'BackgroundColor', [.9 .9 .9]);
end

% --- Executes on button press in checkbox_grid.
function checkbox_grid_Callback(hObject, eventdata, handles)
value = get(hObject, 'Value');
if value
    grid(handles.axes1, 'on')
else
    grid(handles.axes1, 'off')
end

% --- Executes on key press with focus on figure1 or any of its controls.
function figure1_KeyPressFcn(hObject, eventdata, handles)
key = get(hObject, 'CurrentKey');
if strcmp(key, 'escape')
    close(handles.figure1)
end

% --- Executes when user attempts to close figure1.
function figure1_CloseRequestFcn(hObject, eventdata, handles)
global GUI_DATA
if isfield(GUI_DATA, 'count') & GUI_DATA.count > 0
    choice = questdlg('Quit this session?', 'Close', 'Yes', 'No', 'No');
    if strcmp(choice, 'No')
        return
    end
end
delete(hObject)

% --- helper to report an error in the status line
function j_report(handles, msg)
set(handles.text_status, 'String', msg)
beep
